#include "tasks/AdvancedRecipeTask.hpp"
#include <fstream>
#include <iostream>
using namespace fathom;using namespace tasks::advanced;using J=json::Value;using O=J::Object;
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("trace path");int checks=0;std::ifstream in(argv[1]);if(!in)throw std::runtime_error("trace missing");std::string line;while(std::getline(in,line)){const auto row=json::parse(line);const auto&d=definition(row.object().at("source_key").string());AdvancedRecipeTask t(d);auto verify=[&]{const auto bytes=t.continuation();auto r=AdvancedRecipeTask::restoreContinuation(d,bytes);if(bytes!=r->continuation())throw std::runtime_error("idle navigation replay differs");++checks;};auto old=t.capture(Action::SetPlan);t.apply(t.capture(Action::Navigate),O{});verify();bool refused=false;try{t.apply(old,row.object().at("plan"));}catch(const std::exception&){refused=true;}if(!refused)throw std::runtime_error("old token accepted");++checks;for(const auto&step:row.object().at("trace").array())t.apply(t.capture(transferAction(step.object().at("action").string())),step.object().at("payload"));verify();if(t.capture(Action::Navigate).state!=State::Completed)throw std::runtime_error("fixture not completed");t.apply(t.capture(Action::Navigate),O{});verify();}if(checks!=56)throw std::runtime_error("scope count");std::cout<<"PASS "<<checks<<" focused transfer idle-navigation checks across14 source keys\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
